'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),bundle=require('../api-bundle-docs');
const code='const v="3.0.0",i={title:"Trips",version:"1"},s=[{url:"https://sandbox.tripninja.io"}],p={"/trips":{post:{responses:{200:{description:"OK"}}}}},c=JSON.parse("{}"); const Spec={openapi:v,info:i,servers:s,paths:p,components:c};';
test('embedded contracts are extracted as data and receive documented TripNinja token authentication',()=>{const specs=bundle.extract(code);assert.equal(specs.length,1);const plan=bundle.combine(specs,'https://devhub.tripninja.io/');assert.equal(plan.operations.length,1);assert.equal(plan.auth[0].scheme,'token');assert.equal(plan.operations[0].authenticationRequired,true);});
test('downloaded executable expressions are refused without executing them',()=>{globalThis.bundleProbe=0;const bad=code.replace('i={title:"Trips",version:"1"}','i=(()=>{globalThis.bundleProbe=1;return {title:"Bad"};})()');assert.equal(bundle.extract(bad).length,0);assert.equal(globalThis.bundleProbe,0);delete globalThis.bundleProbe;});
test('specification compaction preserves required fields, schemas and paths',()=>{const spec={description:'x'.repeat(500000),required:['id'],properties:{id:{type:'string',example:'large'}}};const compact=bundle.compact(spec);assert.deepEqual(compact,{required:['id'],properties:{id:{type:'string'}}});});
